WITH recent_transactions AS (SELECT * FROM transactions WHERE merchant IN ('Grab', 'Amazon', 'Lazada') AND HOUR(txn_time) BETWEEN 12 AND 19), agg AS (SELECT CASE WHEN amount >= 4500 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END AS amount_bucket, merchant, MAX(amount) AS max_amount, COUNT(DISTINCT amount) AS unique_accounts FROM recent_transactions GROUP BY CASE WHEN amount >= 4500 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END, merchant) SELECT * FROM agg WHERE max_amount >= 2900;
